-- TG-164: els seeds no s'executen en aplicar migracions a bases ja existents.
-- Només omplim els camps es/en coneguts; preservem el català i les edicions existents.
update public.punts_observacio as actual
set textos = jsonb_set(
  jsonb_set(actual.textos, '{es}', traduccions.es || case when jsonb_typeof(actual.textos->'es') = 'object' then actual.textos->'es' else '{}'::jsonb end, true),
  '{en}', traduccions.en || case when jsonb_typeof(actual.textos->'en') = 'object' then actual.textos->'en' else '{}'::jsonb end, true
)
from (values
    ('bellmunt', '{"nom":"Santuario de Bellmunt","descripcio":"Santuario en la cima de Bellmunt, sobre la llanura de Vic. Panorama de 360°; la luz de Osona se nota hacia el sur.","accessibilitat":"Acceso en coche hasta el santuario"}'::jsonb, '{"nom":"Bellmunt Sanctuary","descripcio":"Sanctuary on the summit of Bellmunt above the Vic plain. A 360° panorama; light from Osona is noticeable to the south.","accessibilitat":"Car access to the sanctuary"}'::jsonb),
    ('cap-de-creus', '{"nom":"Cap de Creus","descripcio":"Extremo más oriental de la península, en el Parque Natural del Cap de Creus. Amplio horizonte marino hacia el este, adecuado para ver salir la Luna y el Sol.","accessibilitat":"Acceso en coche hasta el faro"}'::jsonb, '{"nom":"Cap de Creus","descripcio":"Easternmost point of the peninsula, in Cap de Creus Natural Park. Wide sea horizon to the east, ideal for watching the Moon and Sun rise.","accessibilitat":"Car access to the lighthouse"}'::jsonb),
    ('centre-observacio-univers', '{"nom":"Centro de Observación del Universo","descripcio":"Instalación del Parque Astronómico del Montsec, en la vertiente sur de la sierra. El Montsec es Reserva y Destino Turístico Starlight y tiene uno de los cielos más oscuros de Cataluña.","accessibilitat":"Acceso en coche hasta la instalación"}'::jsonb, '{"nom":"Universe Observation Centre","descripcio":"Facility of the Montsec Astronomical Park on the southern slope of the range. Montsec is a Starlight Reserve and Tourist Destination and has one of the darkest skies in Catalonia.","accessibilitat":"Car access to the facility"}'::jsonb),
    ('coll-d-ares', '{"nom":"Coll d''Ares","descripcio":"Paso fronterizo del Ripollès, lejos de grandes poblaciones. Vistas abiertas al Vallespir y al valle de Camprodon.","accessibilitat":"Acceso en coche por la C-38"}'::jsonb, '{"nom":"Coll d''Ares","descripcio":"Border pass in Ripollès, far from large towns. Open views towards Vallespir and the Camprodon valley.","accessibilitat":"Car access via the C-38"}'::jsonb),
    ('coll-de-comiols', '{"nom":"Coll de Comiols","descripcio":"Paso entre la Noguera y el Pallars Jussà, en una zona muy poco poblada al noreste del Montsec.","accessibilitat":"Acceso en coche"}'::jsonb, '{"nom":"Coll de Comiols","descripcio":"Pass between Noguera and Pallars Jussà, in a sparsely populated area northeast of Montsec.","accessibilitat":"Car access"}'::jsonb),
    ('coll-de-pal', '{"nom":"Coll de Pal","descripcio":"Paso de alta montaña en el Parque Natural del Cadí-Moixeró, por encima de los 2.000 m. Cielo muy oscuro y aire seco; la carretera de montaña puede tener nieve en invierno.","accessibilitat":"Acceso en coche por la BV-4024"}'::jsonb, '{"nom":"Coll de Pal","descripcio":"High mountain pass in Cadí-Moixeró Natural Park, above 2,000 m. Very dark sky and dry air; the mountain road may be snowy in winter.","accessibilitat":"Car access via the BV-4024"}'::jsonb),
    ('coll-del-moro', '{"nom":"Coll del Moro","descripcio":"Colina de la Terra Alta con un poblado ibérico en la cima y vistas de 360° sobre la comarca, muy poco poblada.","accessibilitat":"Acceso en coche hasta el poblado ibérico"}'::jsonb, '{"nom":"Coll del Moro","descripcio":"Hill in Terra Alta with an Iberian settlement on its summit and 360° views over the sparsely populated region.","accessibilitat":"Car access to the Iberian settlement"}'::jsonb),
    ('collada-de-toses', '{"nom":"Collada de Toses","descripcio":"Paso de la N-260 entre el Ripollès y la Cerdanya, a unos 1.800 m. Accesible todo el año, con aparcamientos cercanos.","accessibilitat":"Acceso en coche por la N-260"}'::jsonb, '{"nom":"Collada de Toses","descripcio":"Pass on the N-260 between Ripollès and Cerdanya, at about 1,800 m. Accessible year-round, with nearby parking.","accessibilitat":"Car access via the N-260"}'::jsonb),
    ('collformic', '{"nom":"Collformic","descripcio":"Paso del Montseny entre Osona y el Vallès, con aparcamiento. Accesible y con vistas a la llanura de Vic, cuya luz se nota hacia el norte-noroeste.","accessibilitat":"Acceso en coche por la BV-5301"}'::jsonb, '{"nom":"Collformic","descripcio":"Montseny pass between Osona and Vallès, with parking. Accessible and overlooking the Vic plain, whose lights brighten the north-northwestern sky.","accessibilitat":"Car access via the BV-5301"}'::jsonb),
    ('el-cortalet', '{"nom":"el Cortalet (Aiguamolls de l''Empordà)","descripcio":"Centro del Parque Natural de los Aiguamolls de l''Empordà. Terreno llano y abierto hacia el golfo de Roses; la costa aporta luz en temporada alta.","accessibilitat":"Acceso en coche hasta el centro de información"}'::jsonb, '{"nom":"el Cortalet (Aiguamolls de l''Empordà)","descripcio":"Centre of Aiguamolls de l''Empordà Natural Park. Flat terrain open towards the Gulf of Roses; coastal lights become more noticeable in the high season.","accessibilitat":"Car access to the information centre"}'::jsonb),
    ('la-morera-de-montsant', '{"nom":"la Morera de Montsant","descripcio":"Pueblo al pie de los riscos de la sierra de Montsant, dentro del Destino Turístico Starlight. Los riscos tapan el norte; hacia el sur la vista se abre sobre el Priorat.","accessibilitat":"Acceso en coche"}'::jsonb, '{"nom":"la Morera de Montsant","descripcio":"Village below the cliffs of the Montsant range, within the Starlight Tourist Destination. The cliffs block the northern horizon; to the south, the view opens over Priorat.","accessibilitat":"Car access"}'::jsonb),
    ('la-mussara', '{"nom":"la Mussara","descripcio":"Pueblo abandonado al borde de los riscos de la sierra de la Mussara, con vistas abiertas al Camp de Tarragona. El cielo es oscuro hacia el norte, pero al sur se ve la luz del área urbana.","accessibilitat":"Acceso en coche por la carretera de la Mussara"}'::jsonb, '{"nom":"la Mussara","descripcio":"Abandoned village on the edge of the Mussara cliffs, with open views towards Camp de Tarragona. The sky is dark to the north, but urban light is visible to the south.","accessibilitat":"Car access via the Mussara road"}'::jsonb),
    ('mare-de-deu-del-mont', '{"nom":"Santuario de la Mare de Déu del Mont","descripcio":"Santuario en la cima del Mont, entre la Garrotxa y el Alt Empordà, con panorámica de 360° desde los Pirineos hasta el mar.","accessibilitat":"Acceso en coche por una carretera estrecha desde Beuda"}'::jsonb, '{"nom":"Mare de Déu del Mont Sanctuary","descripcio":"Sanctuary on the summit of Mont, between Garrotxa and Alt Empordà, with 360° views from the Pyrenees to the sea.","accessibilitat":"Car access via a narrow road from Beuda"}'::jsonb),
    ('mirador-coll-de-boixols', '{"nom":"Mirador del Coll de Bóixols","descripcio":"Mirador en el collado de Bóixols, entre el Alt Urgell y el Pallars Jussà, en una de las zonas menos pobladas de Cataluña.","accessibilitat":"Acceso en coche por la L-511"}'::jsonb, '{"nom":"Coll de Bóixols Viewpoint","descripcio":"Viewpoint at the Bóixols pass, between Alt Urgell and Pallars Jussà, in one of the least populated areas of Catalonia.","accessibilitat":"Car access via the L-511"}'::jsonb),
    ('mont-caro', '{"nom":"Mont Caro","descripcio":"Cumbre del macizo de Els Ports, con vistas de 360° sobre el delta del Ebro y el Matarranya. Lejos de grandes poblaciones, bajo el cielo oscuro de Els Ports.","accessibilitat":"Carretera asfaltada desde Roquetes; el último tramo hasta la cima puede estar cerrado"}'::jsonb, '{"nom":"Mont Caro","descripcio":"Summit of the Els Ports massif, with 360° views over the Ebro Delta and Matarranya. Far from large towns, beneath the dark sky of Els Ports.","accessibilitat":"Paved road from Roquetes; the final section to the summit may be closed"}'::jsonb),
    ('montgai', '{"nom":"Montgai","descripcio":"Municipio de la llanura de la Noguera, certificado como Destino Turístico Starlight desde 2022. Terreno llano con pocas luces alrededor.","accessibilitat":"Acceso en coche"}'::jsonb, '{"nom":"Montgai","descripcio":"Town on the Noguera plain, certified as a Starlight Tourist Destination since 2022. Flat terrain with little nearby lighting.","accessibilitat":"Car access"}'::jsonb),
    ('observatori-castelltallat', '{"nom":"Observatorio Astronómico de Castelltallat","descripcio":"Observatorio para aficionados en la sierra de Castelltallat, en el Bages. Lugar elevado y alejado de las poblaciones de la comarca.","accessibilitat":"Acceso en coche hasta el observatorio"}'::jsonb, '{"nom":"Castelltallat Astronomical Observatory","descripcio":"Amateur observatory in the Castelltallat hills, in Bages. An elevated site away from the towns of the region.","accessibilitat":"Car access to the observatory"}'::jsonb),
    ('observatori-pujalt', '{"nom":"Observatorio de Pujalt","descripcio":"Observatorio astronómico en el pueblo de Pujalt, en la Alta Anoia, sobre una colina con vistas al cielo de la Cataluña central.","accessibilitat":"Acceso en coche"}'::jsonb, '{"nom":"Pujalt Observatory","descripcio":"Astronomical observatory in the village of Pujalt, in Alta Anoia, on a hill beneath the central Catalan sky.","accessibilitat":"Car access"}'::jsonb),
    ('panta-de-cavallers', '{"nom":"Embalse de Cavallers","descripcio":"Embalse de alta montaña a la entrada del Parque Nacional de Aigüestortes i Estany de Sant Maurici, Reserva Starlight. Cielo muy oscuro; las montañas limitan el horizonte.","accessibilitat":"Acceso en coche hasta la presa"}'::jsonb, '{"nom":"Cavallers Reservoir","descripcio":"High mountain reservoir at the entrance to Aigüestortes i Estany de Sant Maurici National Park, a Starlight Reserve. Very dark sky; mountains limit the horizon.","accessibilitat":"Car access to the dam"}'::jsonb),
    ('plan-de-beret', '{"nom":"Plan de Beret","descripcio":"Meseta de alta montaña en la Val d''Aran, cerca de las fuentes del Garona y la Noguera Pallaresa. Espacio amplio y abierto, muy oscuro fuera de la temporada de esquí.","accessibilitat":"Acceso en coche por la carretera de Beret"}'::jsonb, '{"nom":"Plan de Beret","descripcio":"High mountain plateau in Val d''Aran, near the sources of the Garonne and Noguera Pallaresa. Wide, open area, very dark outside the ski season.","accessibilitat":"Car access via the Beret road"}'::jsonb),
    ('platja-del-trabucador', '{"nom":"Playa del Trabucador","descripcio":"Banco de arena del delta del Ebro con mar a ambos lados. Horizonte llano y despejado, ideal para observar astros cerca del agua al salir y ponerse.","accessibilitat":"Acceso en coche hasta el inicio del banco de arena"}'::jsonb, '{"nom":"Trabucador Beach","descripcio":"Sandbar in the Ebro Delta with sea on both sides. Flat, clear horizon, ideal for observing celestial bodies rising or setting near the water.","accessibilitat":"Car access to the start of the sandbar"}'::jsonb),
    ('port-d-ager', '{"nom":"Puerto de Àger","descripcio":"Paso de la carretera C-12 que da acceso al valle de Àger. Buen lugar para detenerse en la zona protegida del Montsec, lejos de grandes poblaciones.","accessibilitat":"Acceso en coche por la C-12"}'::jsonb, '{"nom":"Port d''Àger Pass","descripcio":"Pass on the C-12 road leading into the Àger valley. A good stopping point in the protected Montsec area, far from large towns.","accessibilitat":"Car access via the C-12"}'::jsonb),
    ('port-de-la-bonaigua', '{"nom":"Port de la Bonaigua","descripcio":"Puerto de montaña a más de 2.000 m entre el Pallars Sobirà y la Val d''Aran. Cielo de alta montaña; la carretera puede cerrarse por nieve.","accessibilitat":"Acceso en coche por la C-28"}'::jsonb, '{"nom":"Port de la Bonaigua","descripcio":"Mountain pass above 2,000 m between Pallars Sobirà and Val d''Aran. High mountain sky; the road may close because of snow.","accessibilitat":"Car access via the C-28"}'::jsonb),
    ('port-del-comte', '{"nom":"el Port del Comte","descripcio":"Zona de la estación de esquí de Port del Comte, en el Solsonès. Gran altitud y pocas luces cercanas fuera de temporada.","accessibilitat":"Acceso en coche hasta la estación de esquí"}'::jsonb, '{"nom":"el Port del Comte","descripcio":"Area around the Port del Comte ski resort in Solsonès. High elevation and few nearby lights outside the ski season.","accessibilitat":"Car access to the ski resort"}'::jsonb),
    ('prades', '{"nom":"Prades","descripcio":"Villa en la meseta de las montañas de Prades, Destino Turístico Starlight junto con la sierra de Montsant. Alberga el Parque Astronómico de las Montañas de Prades; conviene alejarse del núcleo urbano para evitar el alumbrado.","accessibilitat":"Acceso en coche"}'::jsonb, '{"nom":"Prades","descripcio":"Town on the plateau of the Prades Mountains, a Starlight Tourist Destination together with the Montsant range. Home to the Prades Mountains Astronomical Park; move away from the town centre to avoid street lighting.","accessibilitat":"Car access"}'::jsonb),
    ('rasos-de-peguera', '{"nom":"Rasos de Peguera","descripcio":"Meseta de alta montaña al norte del Berguedà. Vistas abiertas al sur sobre la Cataluña central.","accessibilitat":"Acceso en coche por la carretera de los Rasos"}'::jsonb, '{"nom":"Rasos de Peguera","descripcio":"High mountain plateau north of Berguedà. Open views southwards over central Catalonia.","accessibilitat":"Car access via the Rasos road"}'::jsonb),
    ('sant-joan-de-l-erm', '{"nom":"Sant Joan de l''Erm","descripcio":"Claro en un bosque del Alt Urgell, junto al Parque Natural del Alt Pirineu. Muy lejos de cualquier población grande.","accessibilitat":"Pista forestal desde Castellbò"}'::jsonb, '{"nom":"Sant Joan de l''Erm","descripcio":"Clearing in a forest in Alt Urgell, beside Alt Pirineu Natural Park. Very far from any large town.","accessibilitat":"Forest track from Castellbò"}'::jsonb),
    ('santa-fe-de-montseny', '{"nom":"Santa Fe de Montseny","descripcio":"Depresión en el corazón del Montseny rodeada de hayedos. Cielo oscuro en el cénit, pero las cumbres cercanas ocultan el horizonte.","accessibilitat":"Acceso en coche por la BV-5114"}'::jsonb, '{"nom":"Santa Fe de Montseny","descripcio":"Hollow in the heart of Montseny surrounded by beech woods. Dark sky overhead, although nearby peaks block the horizon.","accessibilitat":"Car access via the BV-5114"}'::jsonb),
    ('santuari-del-far', '{"nom":"Santuario del Far","descripcio":"Santuario al borde de un risco de las Guilleries, con vistas al este sobre la Selva. Cielo oscuro hacia el oeste, en dirección al macizo.","accessibilitat":"Acceso en coche hasta el santuario"}'::jsonb, '{"nom":"Far Sanctuary","descripcio":"Sanctuary on the edge of a Guilleries cliff, with eastward views over La Selva. Dark sky towards the massif to the west.","accessibilitat":"Car access to the sanctuary"}'::jsonb),
    ('santuari-del-miracle', '{"nom":"Santuario del Miracle","descripcio":"Santuario en una meseta agrícola del Solsonès con pocas luces, en la Cataluña central.","accessibilitat":"Acceso en coche hasta el santuario"}'::jsonb, '{"nom":"Miracle Sanctuary","descripcio":"Sanctuary on a farming plateau in Solsonès, central Catalonia, with little nearby lighting.","accessibilitat":"Car access to the sanctuary"}'::jsonb),
    ('siurana', '{"nom":"Siurana","descripcio":"Pueblo elevado sobre un espolón rocoso junto al embalse de Siurana, cerca de la sierra de Montsant. Poca contaminación lumínica y horizonte abierto hacia el suroeste.","accessibilitat":"Acceso en coche"}'::jsonb, '{"nom":"Siurana","descripcio":"Village perched on a rocky spur above the Siurana reservoir, close to the Montsant range. Low light pollution and an open horizon to the southwest.","accessibilitat":"Car access"}'::jsonb),
    ('vallter-2000', '{"nom":"Vallter 2000","descripcio":"Circo glaciar en la cabecera del Ter, por encima de los 2.000 m. Cielo muy oscuro; las crestas cierran el horizonte norte y oeste.","accessibilitat":"Acceso en coche por la GIV-5264"}'::jsonb, '{"nom":"Vallter 2000","descripcio":"Glacial cirque near the source of the Ter, above 2,000 m. Very dark sky; ridges block the northern and western horizons.","accessibilitat":"Car access via the GIV-5264"}'::jsonb)
) as traduccions(codi, es, en)
where actual.slug = traduccions.codi and actual.origen = 'OFICIAL';

update public.fenomens_astronomics as actual
set textos = jsonb_set(
  jsonb_set(actual.textos, '{es}', traduccions.es || case when jsonb_typeof(actual.textos->'es') = 'object' then actual.textos->'es' else '{}'::jsonb end, true),
  '{en}', traduccions.en || case when jsonb_typeof(actual.textos->'en') = 'object' then actual.textos->'en' else '{}'::jsonb end, true
)
from (values
    ('alpha-capricornids', '{"nom":"Alfa Capricórnidas","descripcio":"Lluvia estival poco abundante de meteoros lentos que puede ofrecer bólidos vistosos pese a su tasa baja.","consell_general":"No esperes muchos meteoros: observa con paciencia una zona amplia del cielo para detectar los más brillantes."}'::jsonb, '{"nom":"Alpha Capricornids","descripcio":"A sparse summer shower of slow meteors that can produce striking fireballs despite its low rate.","consell_general":"Do not expect many meteors: patiently watch a broad area of the sky for the brightest ones."}'::jsonb),
    ('conjuncio-lluna-jupiter', '{"nom":"Aproximación de la Luna y Júpiter","descripcio":"Desde la Tierra, la Luna y Júpiter parecen cercanos en el cielo, aunque están muy separados en el espacio.","consell_general":"Busca un horizonte despejado y consulta la hora y las condiciones locales; la cercanía es aparente."}'::jsonb, '{"nom":"Close approach of the Moon and Jupiter","descripcio":"From Earth, the Moon and Jupiter appear close in the sky, although they are far apart in space.","consell_general":"Find a clear horizon and check the time and local conditions; the closeness is only apparent."}'::jsonb),
    ('conjuncio-lluna-mart', '{"nom":"Aproximación de la Luna y Marte","descripcio":"Desde la Tierra, la Luna y Marte parecen cercanos en el cielo, aunque están muy separados en el espacio.","consell_general":"Busca un horizonte despejado y consulta la hora y las condiciones locales; la cercanía es aparente."}'::jsonb, '{"nom":"Close approach of the Moon and Mars","descripcio":"From Earth, the Moon and Mars appear close in the sky, although they are far apart in space.","consell_general":"Find a clear horizon and check the time and local conditions; the closeness is only apparent."}'::jsonb),
    ('conjuncio-lluna-venus', '{"nom":"Aproximación de la Luna y Venus","descripcio":"Desde la Tierra, la Luna y Venus parecen cercanos en el cielo, aunque están muy separados en el espacio.","consell_general":"Busca un horizonte despejado y consulta la hora y las condiciones locales; la cercanía es aparente."}'::jsonb, '{"nom":"Close approach of the Moon and Venus","descripcio":"From Earth, the Moon and Venus appear close in the sky, although they are far apart in space.","consell_general":"Find a clear horizon and check the time and local conditions; the closeness is only apparent."}'::jsonb),
    ('conjuncio-mart-jupiter', '{"nom":"Aproximación de Marte y Júpiter","descripcio":"Desde la Tierra, Marte y Júpiter parecen cercanos en el cielo, aunque están muy separados en el espacio.","consell_general":"Busca un horizonte despejado y consulta la hora y las condiciones locales; la cercanía es aparente."}'::jsonb, '{"nom":"Close approach of Mars and Jupiter","descripcio":"From Earth, Mars and Jupiter appear close in the sky, although they are far apart in space.","consell_general":"Find a clear horizon and check the time and local conditions; the closeness is only apparent."}'::jsonb),
    ('draconids', '{"nom":"Dracónidas","descripcio":"Lluvia lenta de origen cometario que suele tener poca actividad, aunque algunos años puede presentar estallidos inesperados.","consell_general":"Obsérvala al anochecer desde un lugar oscuro con una vista amplia del cielo; no necesitas instrumentos."}'::jsonb, '{"nom":"Draconids","descripcio":"A slow cometary meteor shower that is usually quiet, although some years bring unexpected outbursts.","consell_general":"Watch in the evening from a dark place with a wide view of the sky; no equipment is needed."}'::jsonb),
    ('eclipsi-lunar-penumbral', '{"nom":"Eclipse lunar penumbral","descripcio":"La Luna atraviesa la penumbra terrestre y pierde luminosidad gradualmente sin entrar en la sombra central.","consell_general":"El cambio puede ser muy sutil; compara el aspecto de la Luna antes y durante el máximo o toma fotografías con la misma exposición."}'::jsonb, '{"nom":"Penumbral lunar eclipse","descripcio":"The Moon passes through Earth''s penumbra and gradually dims without entering the central shadow.","consell_general":"The change may be very subtle; compare the Moon before and during the peak or take photos with the same exposure."}'::jsonb),
    ('eclipsi-solar-total', '{"nom":"Eclipse solar total","descripcio":"Eclipse en el que la Luna cubre por completo el Sol dentro de la franja de totalidad; desde otros lugares solo se ve una fase parcial.","consell_general":"Fuera de la totalidad, observa el Sol solo con gafas o visores solares conformes con ISO 12312-2; los instrumentos necesitan un filtro solar frontal adecuado."}'::jsonb, '{"nom":"Total solar eclipse","descripcio":"An eclipse in which the Moon fully covers the Sun within the path of totality; elsewhere only a partial phase is visible.","consell_general":"Outside totality, view the Sun only through solar glasses or viewers compliant with ISO 12312-2; optical instruments need a suitable front solar filter."}'::jsonb),
    ('eta-aquariids', '{"nom":"Eta Acuáridas","descripcio":"Lluvia rápida asociada al cometa Halley, muy activa al sur pero con el radiante bajo vista desde Cataluña.","consell_general":"Observa poco antes del amanecer, con el horizonte este o sureste despejado y sin esperar la tasa ideal anunciada."}'::jsonb, '{"nom":"Eta Aquariids","descripcio":"A fast shower associated with Halley''s Comet, very active farther south but with a low radiant as seen from Catalonia.","consell_general":"Watch shortly before dawn with a clear eastern or southeastern horizon; do not expect the advertised ideal rate."}'::jsonb),
    ('geminids', '{"nom":"Gemínidas","descripcio":"Una de las lluvias anuales más abundantes y regulares, con meteoros de velocidad moderada visibles durante buena parte de la noche.","consell_general":"Observa a simple vista desde un lugar oscuro y protegido de luces directas; el radiante asciende durante la noche."}'::jsonb, '{"nom":"Geminids","descripcio":"One of the richest and most regular annual showers, with moderately fast meteors visible for much of the night.","consell_general":"Watch with the naked eye from a dark place sheltered from direct lights; the radiant rises during the night."}'::jsonb),
    ('leonids', '{"nom":"Leónidas","descripcio":"Lluvia de meteoros muy rápidos cuya actividad puede variar cuando la Tierra cruza rastros de polvo del cometa que la origina.","consell_general":"La segunda mitad de la noche suele ser la más adecuada; deja que la vista se adapte a la oscuridad."}'::jsonb, '{"nom":"Leonids","descripcio":"A shower of very fast meteors whose activity can vary as Earth crosses dust trails from its parent comet.","consell_general":"The second half of the night is usually best; give your eyes time to adapt to the darkness."}'::jsonb),
    ('lirids', '{"nom":"Líridas","descripcio":"Lluvia anual de primavera de actividad moderada, con algún meteoro brillante ocasional.","consell_general":"Observa después de medianoche desde un lugar oscuro y evita tener la Luna o luces artificiales en el campo de visión."}'::jsonb, '{"nom":"Lyrids","descripcio":"An annual spring shower with moderate activity and occasional bright meteors.","consell_general":"Watch after midnight from a dark site and keep the Moon and artificial lights out of your field of view."}'::jsonb),
    ('lluna-nova', '{"nom":"Luna nueva","descripcio":"Fase en la que la cara iluminada de la Luna no mira hacia la Tierra. La Luna no es observable, pero el cielo está más oscuro.","consell_general":"Aprovecha la oscuridad para observar objetos tenues; el tiempo y la contaminación lumínica siguen siendo determinantes."}'::jsonb, '{"nom":"New Moon","descripcio":"The Moon’s illuminated side faces away from Earth. The Moon is not visible, but the sky is darker.","consell_general":"Use the darkness to observe faint objects; weather and light pollution still matter."}'::jsonb),
    ('lluna-plena', '{"nom":"Luna llena","descripcio":"Fase en la que vemos casi todo el disco lunar iluminado.","consell_general":"La Luna llena es fácil de ver, pero su luz dificulta observar objetos tenues."}'::jsonb, '{"nom":"Full Moon","descripcio":"A phase when almost the entire lunar disk appears illuminated.","consell_general":"The Full Moon is easy to see, but its light makes faint objects harder to observe."}'::jsonb),
    ('northern-taurids', '{"nom":"Táuridas del Norte","descripcio":"Componente septentrional del complejo de las Táuridas, de tasa baja y máximo amplio, pero con posibilidad de meteoros brillantes.","consell_general":"Observa a simple vista una zona amplia del cielo y cuenta con que pueden pasar bastantes minutos entre meteoros."}'::jsonb, '{"nom":"Northern Taurids","descripcio":"The northern branch of the Taurid complex, with a low rate and broad peak but a chance of bright meteors.","consell_general":"Watch a wide area of the sky with the naked eye and expect several minutes between meteors."}'::jsonb),
    ('orionids', '{"nom":"Oriónidas","descripcio":"Lluvia anual de meteoros rápidos asociada al cometa Halley, con un máximo habitualmente amplio.","consell_general":"Busca un cielo oscuro durante la segunda mitad de la noche y observa una zona amplia, lejos de la Luna."}'::jsonb, '{"nom":"Orionids","descripcio":"An annual shower of fast meteors associated with Halley''s Comet, usually with a broad peak.","consell_general":"Find a dark sky in the second half of the night and watch a broad area away from the Moon."}'::jsonb),
    ('perseids', '{"nom":"Perseidas","descripcio":"Lluvia estival muy activa y popular, con meteoros rápidos y un radiante bien situado desde latitudes medias del hemisferio norte.","consell_general":"Observa tumbado y a simple vista desde un lugar oscuro; mirar una zona amplia alejada del radiante ayuda a ver trazas largas."}'::jsonb, '{"nom":"Perseids","descripcio":"A very active and popular summer shower, with fast meteors and a radiant well placed at mid-northern latitudes.","consell_general":"Lie back and watch with the naked eye from a dark site; a wide area away from the radiant helps reveal long trails."}'::jsonb),
    ('quadrantids', '{"nom":"Cuadrántidas","descripcio":"Lluvia intensa de comienzos de año con un máximo relativamente corto y un radiante favorable en latitudes septentrionales.","consell_general":"Conviene observar lo más cerca posible del máximo, porque la actividad alta dura menos que en otras lluvias."}'::jsonb, '{"nom":"Quadrantids","descripcio":"An intense early-year shower with a relatively short peak and a radiant well placed at northern latitudes.","consell_general":"Observe as close to the peak as possible, because high activity lasts less time than in other showers."}'::jsonb),
    ('southern-delta-aquariids', '{"nom":"Delta Acuáridas del Sur","descripcio":"Lluvia estival de larga duración, más favorable en el hemisferio sur pero parcialmente observable desde Cataluña.","consell_general":"Observa de madrugada hacia un cielo abierto al sur; la tasa real será inferior a la ZHR ideal por la baja altura del radiante."}'::jsonb, '{"nom":"Southern Delta Aquariids","descripcio":"A long-lasting summer shower better placed in the southern hemisphere but partly visible from Catalonia.","consell_general":"Watch before dawn with an open southern sky; the low radiant means the actual rate will be below the ideal ZHR."}'::jsonb),
    ('southern-taurids', '{"nom":"Táuridas del Sur","descripcio":"Lluvia de baja frecuencia y actividad muy extendida en el tiempo, conocida por producir algunos meteoros especialmente brillantes.","consell_general":"Ten paciencia y busca un cielo oscuro; es más probable ver algún meteoro brillante que una sucesión intensa."}'::jsonb, '{"nom":"Southern Taurids","descripcio":"A low-rate shower spread over a long period, known for producing occasional exceptionally bright meteors.","consell_general":"Be patient under a dark sky; a bright meteor is more likely than a dense stream of meteors."}'::jsonb),
    ('superlluna-plena', '{"nom":"Superluna llena","descripcio":"Luna llena cercana al perigeo según el criterio del 90 % del recorrido entre apogeo y perigeo; la diferencia aparente puede ser sutil.","consell_general":"Obsérvala a simple vista. No esperes un cambio de tamaño espectacular sin comparar fotografías tomadas con el mismo equipo."}'::jsonb, '{"nom":"Full Supermoon","descripcio":"A Full Moon near perigee under the 90% criterion along the apogee-to-perigee range; the apparent difference can be subtle.","consell_general":"Observe it with the naked eye. Do not expect a dramatic size difference without comparing photos taken with the same equipment."}'::jsonb),
    ('ursids', '{"nom":"Úrsidas","descripcio":"Lluvia boreal de finales de diciembre, normalmente modesta pero bien situada para observadores del hemisferio norte.","consell_general":"Abrígate, elige un horizonte con poca iluminación y reserva un buen rato para observar."}'::jsonb, '{"nom":"Ursids","descripcio":"A northern-hemisphere shower in late December, usually modest but well placed for northern observers.","consell_general":"Dress warmly, choose a dimly lit horizon and allow plenty of time to watch."}'::jsonb)
) as traduccions(codi, es, en)
where actual.codi = traduccions.codi;

update public.esdeveniments_astronomics as actual
set textos = jsonb_set(
  jsonb_set(actual.textos, '{es}', traduccions.es || case when jsonb_typeof(actual.textos->'es') = 'object' then actual.textos->'es' else '{}'::jsonb end, true),
  '{en}', traduccions.en || case when jsonb_typeof(actual.textos->'en') = 'object' then actual.textos->'en' else '{}'::jsonb end, true
)
