    ('northern-taurids-2026', '{"nota_visibilitat":"Observable desde Cataluña, con actividad baja repartida a lo largo de muchas noches.","consell_observacio":"Busca un cielo oscuro alrededor del 12 de noviembre y espera algún meteoro brillante aislado."}'::jsonb, '{"nota_visibilitat":"Visible from Catalonia, with low activity spread over many nights.","consell_observacio":"Find a dark sky around 12 November and look for an occasional isolated bright meteor."}'::jsonb),
